/**
 * The three faces of the exported PDF, embedded so it prints the same on
 * every device, offline: Source Sans 3 (prose), Source Serif 4 (Scripture)
 * and Cormorant Garamond 600 (titles). Latin subsets from Fontsource 5.2.8;
 * the fonts are under the SIL Open Font License 1.1 (see study-document-fonts.OFL.txt).
 * Imported only when a PDF is made, so the app does not carry it otherwise.
 */
export const STUDY_PDF_FONT_FACES =
  '@font-face{font-family:"Source Sans 3";font-style:normal;font-weight:200 900;font-display:block;src:url(data:font/woff2;base64,) format("woff2");}\n@font-face{font-family:"Source Sans 3";font-style:italic;font-weight:200 900;font-display:block;src:url(data:font/woff2;base64,) format("woff2");}\n@font-face{font-family:"Source Serif 4";font-style:normal;font-weight:200 900;font-display:block;src:url(data:font/woff2;base64,) format("woff2");}\n@font-face{font-family:"Source Serif 4";font-style:italic;font-weight:200 900;font-display:block;src:url(data:font/woff2;base64,) format("woff2");}\n@font-face{font-family:"Cormorant Garamond";font-style:normal;font-weight:600;font-display:block;src:url(data:font/woff2;base64,) format("woff2");}';
